def choose_move(observation):
    def sg(n):
        return 0 if n == 0 else (1 if n > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, tgt):
        return [sg(tgt[0] - src[0]), sg(tgt[1] - src[1])]

    def step_away(src, tgt):
        return [sg(src[0] - tgt[0]), sg(src[1] - tgt[1])]

    def best_by(items, score_fn, default=None):
        best_item = default
        best_score = None
        for item in items or []:
            try:
                s = score_fn(item)
            except Exception:
                continue
            if best_score is None or s > best_score:
                best_score = s
                best_item = item
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    center = ((gw - 1) // 2 if gw > 0 else sx, (gh - 1) // 2 if gh > 0 else sy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = best_by(corners, lambda c: md(c, opp_pos), default=center)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        target = best_by(
            targets,
            lambda c: md(c, opp_pos) - 0.5 * md(c, self_pos),
            default=None,
        )
        if target is None:
            return step_toward(self_pos, center)
        return step_toward(self_pos, target)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("food") or []
    target = best_by(
        resources,
        lambda r: md(r, opp_pos) - md(r, self_pos),
        default=None,
    )
    if target is not None:
        return step_toward(self_pos, target)

    if ox == sx and oy == sy:
        return [0, 0]
    if gw > 0 or gh > 0:
        return step_toward(self_pos, center)
    return step_away(self_pos, opp_pos)

